// Preact twins of the DS builders in components.ts (badge, layerCard, provenanceStrip) for the TSX shell.
// They render exactly the DOM that components.js builds; setLevel() from components.js still drives the card
// depth imperatively (the cockpit and the "Abrir tudo em Prova" button mutate .l3 nodes outside Preact).
// Source of truth: this .tsx file. ui.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, render } from "../vendor/preact/preact.module.js";
import { PROV, nextLayerId, setLevel } from "./components.js";
/** Badge element. kind is val|est|sim|nd|ok|bad|warn; text overrides the label. */
export function Badge({ kind, text }) {
    const p = PROV[kind];
    return h("span", { class: "prov " + kind, title: p ? p.title : undefined }, text || (p ? p.label : kind));
}
/** Three-layer card (Resposta, Por quê, Prova). The id counter is shared with components.layerCard. */
export function LayerCard({ title, badge, globalBadge, answer, why, proof = [], level = 0, surface }) {
    const id = nextLayerId();
    const lvl = Math.max(0, Math.min(2, level ?? 0));
    const showBadge = badge && badge !== globalBadge;
    return (h("section", { class: "l3 " + (surface || "solid"), "data-level": String(lvl), "aria-labelledby": id + "-t" },
        h("header", null,
            h("h2", { class: "h-card", id: id + "-t" }, title),
            showBadge ? h(Badge, { kind: badge }) : null),
        h("p", { class: "l3-ans" }, answer),
        h("div", { class: "l3-why", id: id + "-why" },
            h("span", { class: "lbl-s" }, "Por qu\u00EA"),
            typeof why === "string" ? h("p", null, why) : why),
        h("div", { class: "l3-proof", id: id + "-proof" },
            h("span", { class: "lbl-s" }, "Prova"),
            h("dl", null, proof.map(([k, v]) => h(Fragment, null,
                h("dt", null, k),
                h("dd", null, v))))),
        h("div", { class: "l3-tabs", role: "group", "aria-label": "Profundidade do cartão " + title }, ["1 Resposta", "2 Por quê", "3 Prova"].map((label, i) => (h("button", { type: "button", "aria-pressed": i === lvl, "aria-controls": i === 0 ? undefined : id + (i === 1 ? "-why" : "-proof"), onClick: (e) => setLevel(e.currentTarget.closest(".l3"), i) }, label))))));
}
/** Provenance strip: one component instead of loose status chips. api is ok|off|unknown|null. */
export function ProvStrip({ items = [], api = null, note = null }) {
    return (h("div", { class: "pstrip glass", role: "status", "aria-label": "Proced\u00EAncia dos dados" },
        h("span", { class: "k" }, "Proced\u00EAncia"),
        items.map(it => h("span", { class: "it" },
            h(Badge, { kind: it.kind }),
            it.text)),
        api ? h("span", { class: "it" },
            "API:",
            h("span", { class: api === "ok" ? "api-ok" : "api-off" }, api === "ok" ? "OK" : api === "off" ? "offline" : "verificando…")) : null,
        note ? h("span", { class: "it t3" }, note) : null));
}
/**
 * Render a view into the router outlet. The router empties the outlet (replaceChildren) before every route, so
 * any previous Preact tree is unmounted first: render(null) only removes nodes that are still attached.
 */
export function mount(outlet, tree) {
    render(null, outlet);
    outlet.replaceChildren();
    render(tree, outlet);
}
